log.command:
python3 - <<'EOF'
p='compositions/screen-mobile-inbox.html'; s=open(p).read()
s=s.replace("""        #mobile-inbox {
          position: absolute;
          inset: 0;
          background: var(--window);""","""        #mobile-inbox {
          position: absolute;
          inset: 0;
        }
        #mobile-inbox .sk {
          background: var(--window);""",1)
open(p,'w').write(s)
p='compositions/brand-kit.html'; s=open(p).read()
s=s.replace("""        #brand-kit {
          position: absolute;
          inset: 0;
          background:""","""        #brand-kit {
          position: absolute;
          inset: 0;
        }
        #brand-kit .sk {
          background:""",1)
open(p,'w').write(s)
p='assets/ui/titan-ui.css'; s=open(p).read()
s=s.replace("/* ---------- Base ---------- */","/* ---------- Base ---------- */\n/* .sk = the wrapper inside each screen that carries its theme and state settings */\n.t-ui.sk {\n  position: absolute;\n  inset: 0;\n}",1)
open(p,'w').write(s)
import re
p='index.html'; s=open(p).read()
s=re.sub(r' data-(theme|view|variant|stage)="\w+"(?= data-start)','',s)
s=s.replace(" data-view: dashboard | reply | done"," (state is set inside the screen file)")
s=s.replace(" data-variant: casual | formal | spanish | prompt | generating","")
s=s.replace(" data-stage: welcome | summary | booked","")
open(p,'w').write(s)
EOF
grep -n "data-theme\|data-view\|data-variant\|data-stage" index.html; npx --yes hyperframes@0.8.151 check 2>&1 | grep -E "✗|error|Layout|issues|Contrast|pass|◇" | head -30

