  padding: 6px 10px 4px;
  font-size: 11px;
  color: var(--muted);
}
.t-menu .t-mi {
  display: flex;
  align-items: center;
  height: 32px;
  padding: 0 10px;
  border-radius: 6px;
  color: var(--text-2);
}
